entries.commands:
# ===== 以太口转二层并划 VLAN（华为 AR 路由器）=====
system-view
vlan {{vlan_id}}
 description {{vlan_name}}
 quit
interface GigabitEthernet {{port}}
 portswitch
 port link-type access
 port default vlan {{vlan_id}}
 quit
display port vlan
save
y

# ===== Trunk 上联（华为 AR 路由器）=====
system-view
interface GigabitEthernet {{port}}
 portswitch
 port link-type trunk
 port trunk allow-pass vlan {{vlan_list}}
 port trunk pvid vlan {{pvid}}
 quit
save
y

# ===== 静态路由（华为 AR 路由器）=====
system-view
ip route-static {{dest_net}} {{mask}} {{next_hop}}
ip route-static 0.0.0.0 0.0.0.0 {{next_hop}}
! 双出口浮动备份：主出口 preference 默认 60，备份口设 70
ip route-static 0.0.0.0 0.0.0.0 {{backup_hop}} preference {{preference}}
display ip routing-table
display ip routing-table 0.0.0.0
save
y

# ===== OSPF + 引入静态路由（华为 AR 路由器）=====
system-view
ospf {{process_id}} router-id {{router_id}}
 area {{area_id}}
  network {{network}} {{wildcard}}
  quit
 import-route static
 silent-interface GigabitEthernet{{silent_port}}
 quit
display ospf peer
display ospf lsdb
save
y

# ===== 基本 ACL + 接口过滤（华为 AR 路由器）=====
system-view
acl number {{acl_number}}
 rule 5 permit source {{src_net}} {{src_wild}}
 quit
! 接口双向过滤（inbound / outbound）
interface GigabitEthernet {{port}}
 traffic-filter inbound acl {{acl_number}}
 traffic-filter outbound acl {{acl_number}}
 quit
display acl {{acl_number}}
save
y

# ===== NAT / Easy IP + 地址池（华为 AR 路由器）=====
system-view
acl number {{acl_number}}
 rule 5 permit source {{src_net}} {{src_wild}}
 quit
! ---- 方案A：Easy IP（借用出接口地址，最常用）----
nat outbound {{acl_number}}
! ---- 方案B：公网地址池 PAT ----
! nat address-group {{group_id}}
!  section {{section_start}} {{section_end}}
! nat outbound {{acl_number}} address-group {{group_id}}
! ---- 服务器端口映射（公网 8080 → 内网 80）----
! nat server protocol tcp global {{public_ip}} {{public_port}} inside {{inside_server}} {{inside_port}}
display nat outbound
display nat session all
save
y

# ===== Console 口令（华为 AR 路由器）=====
system-view
user-interface console 0
 authentication-mode password
 set authentication password cipher {{console_password}}
 user privilege level {{privilege}}
 idle-timeout {{timeout_min}}
 quit
save
y

# ===== SNMP 配置（华为 AR 路由器）=====
system-view
snmp-agent
snmp-agent sys-info version v2c
snmp-agent community read cipher {{ro_community}}
snmp-agent community write cipher {{rw_community}}
snmp-agent sys-info location {{location}}
snmp-agent sys-info contact {{contact}}
snmp-agent target-host trap address udp-domain {{nms_ip}} params securityname cipher {{ro_community}} v2c
snmp-agent trap enable
snmp-agent trap source GigabitEthernet{{trap_source_port}}
display snmp-agent sys-info
save
y
